#ifndef MATERIAL_SHARED_RETAINED_H
#define MATERIAL_SHARED_RETAINED_H
#include "material_shared_winding.h"
#include "material_shared_target_integral.h"
namespace shared_target {
static std::vector<std::string> columns(const std::string&s){std::vector<std::string>out;size_t a=0;for(size_t j=0;j<=s.size();j++)if(j==s.size()||s[j]==','){out.push_back(s.substr(a,j-a));a=j+1;}return out;}
static Q number(const std::string&s){char*end=nullptr;Q q=strtoflt128(s.c_str(),&end);need(end&&*end==0&&finiteq(q),"finite round-trip Q128 ledger number");return q;}
struct RetainedSource {uint64_t cell=0;int classification=-1;bool geometry=false,empty=false;sf::RealBounds real;};
static std::vector<RetainedSource> retained_sources(const std::string&call,const std::string&bounds,const st::Factory&f){std::vector<RetainedSource>out(384);std::string line;std::ifstream input(call+"/source_target_contributions.csv");need(bool(input),"retained all384 source classification");std::getline(input,line);std::set<int>seen;while(std::getline(input,line)){auto c=columns(line);int s=std::stoi(c[0]);need(s>=0&&s<384&&seen.insert(s).second,"unique retained source classification");auto&r=out[s];r.cell=std::stoull(c[1]);r.classification=std::stoi(c[2]);r.geometry=c[3]=="1";need(r.cell==f.cell[f.triangle[s].cell]&&r.classification>=0&&r.classification<=2,"retained physical source identity");}need(seen.size()==384,"all retained source classifications");std::ifstream bound(bounds+"/source_real_bounds.csv");need(bool(bound),"retained same-function whole-real source proof");std::getline(bound,line);seen.clear();while(std::getline(bound,line)){auto c=columns(line);int s=std::stoi(c[0]);need(s>=0&&s<384&&seen.insert(s).second&&c[3]=="1","unique valid retained real bound");auto inflate=[](const std::string&s){R value=strtold(s.c_str(),nullptr);return Q(nextafterl(value,INFINITY));};out[s].real.L=inflate(c[6]);out[s].real.displacement[0]=inflate(c[7]);out[s].real.displacement[1]=inflate(c[8]);need(out[s].real.L<1,"retained source globally injective");}need(seen.size()==384,"all retained real bounds");return out;}
static std::vector<Thermal> retained_context(const std::string&call,const st::Factory&f,const sf::FrozenThermal&heat){std::ifstream input(call+"/frozen_geometric_EOS_context.csv");need(bool(input),"retained discrete compatible EOS context");std::vector<Thermal>out(24);std::string line;std::getline(input,line);std::set<uint64_t>seen;while(std::getline(input,line)){auto c=columns(line);uint64_t cell=std::stoull(c[0]);auto i=std::find(f.cell.begin(),f.cell.end(),cell);need(i!=f.cell.end()&&seen.insert(cell).second,"one retained EOS physical cell");out[i-f.cell.begin()].delta=std::stod(c[6]);out[i-f.cell.begin()].delta_dot=std::stod(c[7]);}need(seen.size()==24,"all retained EOS cell contexts");bind_context(out,f,heat);return out;}
static std::vector<Domain> retained_domains(const std::string&call,const std::vector<RetainedSource>&source){std::vector<Domain>out(384);for(int s=0;s<384;s++){out[s].source=s;out[s].empty=source[s].empty;}std::string line;std::ifstream nodes(call+"/actual_target_nodes.csv"),edges(call+"/actual_target_boundaries.csv"),loops(call+"/actual_target_loops.csv");need(nodes&&edges&&loops,"retained actual complete-domain packets");std::getline(nodes,line);while(std::getline(nodes,line)){auto c=columns(line);int s=std::stoi(c[0]),j=std::stoi(c[1]);need(source[s].geometry&&source[s].classification==2&&j==int(out[s].node.size()),"retained ordered domain node identity");Node n;n.vertex=std::stoi(c[2]);n.p[0]=S(number(c[3]),number(c[4]));n.p[1]=S(number(c[5]),number(c[6]));std::string a=c[7];size_t pos=0;while(pos<a.size()){size_t next=a.find(';',pos);if(next==std::string::npos)break;n.active.push_back(std::stoi(a.substr(pos,next-pos)));pos=next+1;}out[s].node.push_back(n);}std::getline(edges,line);while(std::getline(edges,line)){auto c=columns(line);int s=std::stoi(c[0]),j=std::stoi(c[1]);need(j==int(out[s].boundary.size()),"retained ordered domain boundary");out[s].boundary.push_back({std::stoi(c[2]),std::stoi(c[3]),std::stoi(c[4]),S(number(c[5]),number(c[6])),S(number(c[7]),number(c[8]))});}std::getline(loops,line);while(std::getline(loops,line)){auto c=columns(line);int s=std::stoi(c[0]),j=std::stoi(c[1]);need(j==int(out[s].loop.size()),"retained ordered domain loop");Loop loop;loop.anchor[0]=number(c[2]);loop.anchor[1]=number(c[3]);if(c.size()>=7&&c[6]=="0"){loop.fan_eligible=false;loop.star_lower=0;if(c.size()>=8)snprintf(loop.fan_reason,sizeof(loop.fan_reason),"%s",c[7].c_str());}else{loop.star_lower=number(c[4]);loop.fan_eligible=loop.star_lower>0;}std::string a=c[5];size_t pos=0;while(pos<a.size()){size_t next=a.find(';',pos);if(next==std::string::npos)break;loop.boundary.push_back(std::stoi(a.substr(pos,next-pos)));pos=next+1;}out[s].loop.push_back(loop);}for(int s=0;s<384;s++)if(source[s].classification==2&&source[s].geometry&&!source[s].empty)need(!out[s].loop.empty(),"retained actual intersection loop exists");return out;}
static void write_domain_packets(const std::string&dest,const std::vector<Domain>&domains,const std::vector<int>&complete){FILE*nodes=fopen((dest+"/actual_target_nodes.csv").c_str(),"w"),*boundaries=fopen((dest+"/actual_target_boundaries.csv").c_str(),"w"),*loops=fopen((dest+"/actual_target_loops.csv").c_str(),"w");need(nodes&&boundaries&&loops,"retained and newly completed actual domain packet");fprintf(nodes,"source,node,original_vertex_id,x,x_radius,y,y_radius,active_plane_indices\n");fprintf(boundaries,"source,boundary,first,last,canonical_edge,parameter_lo,parameter_lo_radius,parameter_hi,parameter_hi_radius\n");fprintf(loops,"source,loop,anchor_x,anchor_y,positive_star_J_lower,boundary_indices,fan_eligible,fan_reason\n");for(int s=0;s<384;s++)if(complete[s]){const auto&d=domains[s];for(size_t j=0;j<d.node.size();j++){const auto&n=d.node[j];std::string a;for(int k:n.active)a+=std::to_string(k)+";";fprintf(nodes,"%d,%zu,%d,%s,%s,%s,%s,%s\n",s,j,n.vertex,qs(n.p[0].n).c_str(),qs(n.p[0].e).c_str(),qs(n.p[1].n).c_str(),qs(n.p[1].e).c_str(),a.c_str());}for(size_t j=0;j<d.boundary.size();j++){const auto&b=d.boundary[j];fprintf(boundaries,"%d,%zu,%d,%d,%d,%s,%s,%s,%s\n",s,j,b.first,b.last,b.edge,qs(b.lo.n).c_str(),qs(b.lo.e).c_str(),qs(b.hi.n).c_str(),qs(b.hi.e).c_str());}for(size_t j=0;j<d.loop.size();j++){const auto&l=d.loop[j];std::string a;for(int k:l.boundary)a+=std::to_string(k)+";";fprintf(loops,"%d,%zu,%s,%s,%s,%s,%d,%s\n",s,j,qs(l.anchor[0]).c_str(),qs(l.anchor[1]).c_str(),qs(l.star_lower).c_str(),a.c_str(),l.fan_eligible,l.fan_reason);}}fclose(nodes);fclose(boundaries);fclose(loops);}
static std::array<Q,12> original_tolerances(const std::string&path){std::ifstream input(path);need(bool(input),"ORIGINAL whole-target tolerance manifest source");std::string line;std::getline(input,line);auto names=columns(line);int column=-1;for(size_t j=0;j<names.size();j++)if(names[j]=="unchanged_physical_tolerance")column=j;need(column>=0,"original full physical tau schema");std::array<Q,12>tau;int count=0;while(std::getline(input,line)){auto c=columns(line);if(c[0]!="68526")continue;need(count<12,"original target has twelve tolerances");static const char*original_names[12]={"mass","px","py","angular","K","U","volume","qx","qy","polar","thermal_rate","potential"};need(c[1]==original_names[count],"original tolerance moment identity and order");tau[count++]=mf::FP<Q>::down(number(c[column]));}need(count==12,"all twelve original whole-target physical criteria");for(Q q:tau)need(q>0,"original physical tau positive");return tau;}
static void retained_roots(const std::string&path,std::map<int,Edge>&edges,const std::vector<Plane>&planes){std::ifstream input(path);need(bool(input),"retained canonical root parameter packets");std::string line;std::getline(input,line);while(std::getline(input,line)){auto c=columns(line);int key=std::stoi(c[0]);uint64_t competitor=std::stoull(c[1]);auto p=std::find_if(planes.begin(),planes.end(),[&](const Plane&p){return p.competitor==competitor;});need(p!=planes.end()&&edges.count(key),"retained canonical edge/plane identity");auto&e=edges.at(key);if(e.events.empty())e.events.resize(planes.size());auto&r=e.events[p-planes.begin()];r.complete=c[2]=="1";r.evaluations=std::stoull(c[3]);need(r.complete,"retained root packets are complete");if(c[4]!="-1"){need(std::stoull(c[4])==r.root.size(),"ordered retained roots");r.root.push_back({S(number(c[6]),number(c[7])),std::stoi(c[8])});}snprintf(r.reason,sizeof(r.reason),"retained_complete_canonical_root_packet");}}
static void coverage_overlay(const std::string&call,std::vector<RetainedSource>&source){std::ifstream input(call+"/source_coverage.csv");need(bool(input),"retained completed winding coverage ledger");std::string line;std::getline(input,line);std::set<int>seen;while(std::getline(input,line)){auto c=columns(line);int s=std::stoi(c[0]);need(s>=0&&s<384&&seen.insert(s).second&&std::stoi(c[2])==source[s].classification,"retained winding source identity");if(source[s].classification==2){source[s].geometry=c[3]=="1";source[s].empty=c[5]=="1";}}need(seen.size()==384,"all384 coverage rows retained");}
struct WholeGroup {Accumulator integral;std::vector<int>source;bool complete=false;};
static WholeGroup retained_whole_group(const std::string&path,const std::vector<RetainedSource>&sources){WholeGroup out;std::ifstream input(path+"/whole_inside_source_integrals.csv");need(bool(input),"retained four actual whole-source integrals");std::string line;std::getline(input,line);std::set<int>seen;while(std::getline(input,line)){auto c=columns(line);int s=std::stoi(c[0]);need(s>=0&&s<384&&sources[s].classification==1&&seen.insert(s).second&&c[1]=="1","retained whole-source group member complete");out.source.push_back(s);out.integral.points+=std::stoull(c[4]);}need(seen.size()==4,"exact four whole-source group members");std::ifstream values(path+"/PARTIAL_four_source_all12_errors.csv");need(bool(values),"retained group all12 values and absolute errors");std::getline(values,line);int k=0;while(std::getline(values,line)){auto c=columns(line);need(k<12&&c[0]==moment_name[k]&&c[1]=="1","retained group moment identity/completeness");out.integral.moment[k]=S(number(c[2]),number(c[3]));out.integral.remainder[k]=number(c[4]);k++;}need(k==12,"all twelve moments of retained group");out.complete=true;return out;}
}
#endif
